export function LangCards({ children }: { children: ReactNode }) {
  return <div className="zd-cards zd-cards_lang">{children}</div>;
}

export function LangCard({
  logo,
  title,
  href,
  children,
}: {
  logo: keyof typeof logos;
  title: string;
  href: string;
  children: ReactNode;
}) {
  const isExternal = /^https?:\/\//.test(href);
  return (
    <a
      className="zd-card zd-lang-card"
      href={href}
      {...(isExternal ? { target: "_blank", rel: "noopener noreferrer" } : {})}
    >
      <div className="zd-card_header">
        <div className="zd-lang-card_logo">{logos[logo]}</div>
        <div className="zd-card_title">{title}</div>
      </div>
      <div className="zd-card_body">{children}</div>
    </a>
  );
}
